            <button 
              onClick={handleFollowMaster}
              disabled={!inputCode}
              className="w-full bg-white text-slate-900 font-bold py-4 px-6 rounded-xl flex items-center justify-center transition-all active:scale-95 disabled:opacity-50"
            >
              <Users size={20} className="mr-2" />
              Seguir um Mestre
            </button>
            {error && <p className="text-red-400 text-sm text-center">{error}</p>}
          </div>
        </div>

        <div className="mt-auto text-slate-500 text-xs text-center pb-4">
          v1.0.0 &bull; Alta precisão GPS habilitada
        </div>
      </div>
    );
  }

  return (
    <div className="h-full w-full relative">
      {/* Map View */}
      <div className="absolute inset-0">
        <MapComponent 
          userPos={userPos} 
          masterPos={masterPos} 
          trip={currentTrip} 
          role={role} 
        />
      </div>

      {/* Floating Header */}
      <div className="absolute top-4 left-4 right-4 z-[500] pointer-events-none">
        <div className="bg-white/90 backdrop-blur-md rounded-2xl p-4 shadow-lg border border-white/50 flex items-center justify-between pointer-events-auto">
          <div className="flex items-center space-x-3">
            <div className={`${role === UserRole.MESTRE ? 'bg-blue-600' : 'bg-red-500'} w-10 h-10 rounded-full flex items-center justify-center text-white shadow-inner`}>
              {role === UserRole.MESTRE ? '👑' : '🚗'}
            </div>
            <div>
              <h2 className="font-bold text-slate-900 leading-none">
                {role === UserRole.MESTRE ? 'Você é o Mestre' : 'Seguindo Mestre'}
              </h2>
              <p className="text-xs text-slate-500 mt-1">
                {currentTrip?.isActive ? 'Viagem ativa • Gravando rastro' : 'Mestre chegou ao destino'}
              </p>
            </div>
          </div>
          <button 
            onClick={exitTrip}
            className="p-2 text-slate-400 hover:text-red-500 transition-colors"
          >
            <LogOut size={20} />
          </button>
        </div>
      </div>

      {/* Bottom Sheet */}
      <div 
        className={`absolute bottom-0 left-0 right-0 bg-white shadow-[0_-10px_40px_rgba(0,0,0,0.1)] rounded-t-3xl z-[1000] bottom-sheet border-t border-slate-100 transition-transform duration-300 transform ${isBottomSheetOpen ? 'translate-y-0' : 'translate-y-[calc(100%-80px)]'}`}
      >
        {/* Handle */}
        <div 
          className="w-full flex flex-col items-center py-3 cursor-pointer"
          onClick={() => setIsBottomSheetOpen(!isBottomSheetOpen)}
        >
          <div className="w-12 h-1.5 bg-slate-200 rounded-full mb-1"></div>
          {!isBottomSheetOpen && <span className="text-xs font-semibold text-slate-400 uppercase tracking-widest">Ver Detalhes</span>}
        </div>

        <div className="px-6 pb-8 overflow-y-auto max-h-[60vh]">
          {role === UserRole.MESTRE && (
            <div className="space-y-6">
              <div className="flex items-center justify-between">
                <div>
                  <label className="text-xs font-bold text-slate-400 uppercase tracking-wider block mb-1">Código de Compartilhamento</label>
                  <div className="text-3xl font-mono font-bold text-blue-600 tracking-tighter">
                    {currentTrip?.code}
                  </div>
                </div>
                <button 
                  onClick={copyCode}
                  className={`flex items-center px-4 py-2 rounded-full text-sm font-bold transition-all ${copied ? 'bg-green-100 text-green-600' : 'bg-blue-50 text-blue-600 active:bg-blue-100'}`}
                >
                  {copied ? <Check size={16} className="mr-1.5" /> : <Copy size={16} className="mr-1.5" />}
                  {copied ? 'Copiado!' : 'Copiar'}
                </button>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
                  <div className="text-slate-400 text-xs mb-1">Rastro Gravado</div>
                  <div className="text-xl font-bold">{currentTrip?.path.length || 0} pts</div>
                </div>
                <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
                  <div className="text-slate-400 text-xs mb-1">Duração</div>
                  <div className="text-xl font-bold">
                    {currentTrip ? Math.floor((Date.now() - currentTrip.createdAt) / 60000) : 0} min
                  </div>
                </div>
              </div>

              {currentTrip?.isActive ? (
                <button 
                  onClick={stopTrip}
                  className="w-full bg-red-500 hover:bg-red-600 text-white font-bold py-4 rounded-2xl flex items-center justify-center shadow-lg shadow-red-500/20 active:scale-95 transition-all"
                >
                  <StopCircle className="mr-2" size={24} />
                  Cheguei ao Destino
                </button>
              ) : (
                <div className="bg-green-100 text-green-700 p-4 rounded-2xl flex items-center justify-center font-bold">
                  <Check className="mr-2" /> Viagem Finalizada e Salva
                </div>
              )}

              <button className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold flex items-center justify-center active:scale-95 transition-all">
                <Share2 className="mr-2" size={20} />
                Enviar Convite (WhatsApp)
              </button>
            </div>
          )}

          {role === UserRole.SEGUIDOR && (
            <div className="space-y-6">
              <div className="flex items-start space-x-4">
                <div className="bg-slate-100 p-3 rounded-2xl">
                  <MapPin className="text-blue-600" size={24} />
                </div>
                <div>
                  <h3 className="text-lg font-bold text-slate-900">Seguindo Rota do Mestre</h3>
                  <p className="text-sm text-slate-500">
                    O Mestre está {currentTrip?.isActive ? 'ativo agora' : 'offline (viagem concluída)'}.
                    Siga a linha azul no mapa.
                  </p>
                </div>
              </div>

              <div className="bg-blue-50 p-6 rounded-3xl border border-blue-100">
                <div className="flex justify-between items-center mb-4">
                  <span className="text-blue-600 text-sm font-bold uppercase">Status do Comboio</span>
                  <div className="flex items-center">
                    <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse mr-2"></div>
                    <span className="text-xs text-green-600 font-bold">CONECTADO</span>
                  </div>
                </div>
                <div className="flex items-end justify-between">
                  <div>
                    <div className="text-3xl font-bold text-slate-900">{currentTrip?.path.length || 0}</div>
                    <div className="text-xs text-slate-500 font-medium">Coordenadas Gravadas</div>
                  </div>
                  <Navigation size={40} className="text-blue-200" />
                </div>
              </div>

              <div className="flex items-center justify-center space-x-3 text-slate-400 text-xs py-2">
                <Users size={14} />
                <span>Código do Grupo: <span className="font-bold">{currentTrip?.code}</span></span>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default App;

export interface GeoPoint {
  lat: number;
  lng: number;
  timestamp: number;
}

export interface Destination {
  lat: number;
  lng: number;
  name: string;
}

export enum UserRole {
  MESTRE = 'MESTRE',
  SEGUIDOR = 'SEGUIDOR',
  NONE = 'NONE'
}

export interface Trip {
  id: string;
  code: string;
  name: string;
  masterId: string;
  destination?: Destination;
  path: GeoPoint[];
  isActive: boolean;
  createdAt: number;
}

export interface AppState {
  role: UserRole;
  currentTrip: Trip | null;
  userPosition: GeoPoint | null;
  masterPosition: GeoPoint | null;
}

import React, { useEffect, useRef } from 'react';
import { MapContainer, TileLayer, Marker, Polyline, useMap, ZoomControl, useMapEvents } from 'react-leaflet';
import L from 'leaflet';
import { Trip, GeoPoint, UserRole, Destination } from '../types';

interface MapProps {
  userPos: GeoPoint | null;
  masterPos: GeoPoint | null;
  trip: Trip | null;
  role: UserRole;
  onMapClick?: (lat: number, lng: number) => void;
  isSelectingDestination?: boolean;
}

const RecenterMap: React.FC<{ pos: GeoPoint | null }> = ({ pos }) => {
  const map = useMap();
  useEffect(() => {
    if (pos) {
      map.setView([pos.lat, pos.lng], map.getZoom());
    }
  }, [pos, map]);
  return null;
};

const MapEvents: React.FC<{ onClick: (lat: number, lng: number) => void }> = ({ onClick }) => {
  useMapEvents({
    click: (e) => onClick(e.latlng.lat, e.latlng.lng),
  });
  return null;
};

const MapComponent: React.FC<MapProps> = ({ userPos, masterPos, trip, role, onMapClick, isSelectingDestination }) => {
  const masterIcon = L.divIcon({
    className: 'custom-marker-master',
    html: '<div style="width: 24px; height: 24px; display: flex; align-items: center; justify-content: center; color: white;">👑</div>',
    iconSize: [30, 30],
    iconAnchor: [15, 15]
  });

  const followerIcon = L.divIcon({
    className: 'custom-marker-follower',
    html: '<div style="width: 24px; height: 24px; display: flex; align-items: center; justify-content: center; color: white;">🚗</div>',
    iconSize: [30, 30],
    iconAnchor: [15, 15]
  });

  const destIcon = L.divIcon({
    className: 'bg-green-500 border-2 border-white rounded-lg shadow-lg',
    html: '<div style="width: 24px; height: 24px; display: flex; align-items: center; justify-content: center; color: white;">🏁</div>',
    iconSize: [30, 30],
    iconAnchor: [15, 30]
  });

  const polylinePositions = trip?.path.map(p => [p.lat, p.lng] as [number, number]) || [];

  // Linha de guia (Posição atual -> Destino)
  const guideLine = (userPos && trip?.destination) 
    ? [[userPos.lat, userPos.lng], [trip.destination.lat, trip.destination.lng]] as [number, number][]
    : [];

  return (
    <div className="w-full h-full relative">
      <MapContainer
        center={userPos ? [userPos.lat, userPos.lng] : [-23.5505, -46.6333]}
        zoom={15}
        scrollWheelZoom={true}
        className="w-full h-full"
        zoomControl={false}
      >
        <TileLayer
          attribution='&copy; OpenStreetMap contributors'
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />
        <ZoomControl position="topright" />

        {isSelectingDestination && onMapClick && <MapEvents onClick={onMapClick} />}

        {/* Rastro percorrido */}
        {polylinePositions.length > 0 && (
          <Polyline positions={polylinePositions} color="#3b82f6" weight={5} opacity={0.7} />
        )}

        {/* Linha de guia para o destino (tracejada) */}
        {guideLine.length > 2 && (
          <Polyline positions={guideLine} color="#10b981" weight={3} dashArray="10, 10" opacity={0.5} />
        )}

        {/* Destino */}
        {trip?.destination && (
          <Marker position={[trip.destination.lat, trip.destination.lng]} icon={destIcon} />
        )}

        {/* Usuário Atual */}
        {userPos && (
          <Marker position={[userPos.lat, userPos.lng]} icon={role === UserRole.MESTRE ? masterIcon : followerIcon} />
        )}

        {/* Mestre (visto pelo seguidor) */}
        {role === UserRole.SEGUIDOR && masterPos && (
          <Marker position={[masterPos.lat, masterPos.lng]} icon={masterIcon} />
        )}

        {!isSelectingDestination && <RecenterMap pos={userPos} />}
      </MapContainer>
    </div>
  );
};

export default MapComponent;

import React, { useState, useEffect, useRef } from 'react';
import { UserRole, Trip, GeoPoint, Destination } from './types';
import MapComponent from './components/MapComponent';
import { storageService } from './services/storage';
import { Navigation, Play, StopCircle, Share2, Users, MapPin, ChevronUp, ChevronDown, Copy, Check, LogOut, Search, Map as MapIcon, Loader2 } from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole>(UserRole.NONE);
  const [isConfiguringTrip, setIsConfiguringTrip] = useState(false);
  const [currentTrip, setCurrentTrip] = useState<Trip | null>(null);
  const [userPos, setUserPos] = useState<GeoPoint | null>(null);
  const [masterPos, setMasterPos] = useState<GeoPoint | null>(null);
  const [isBottomSheetOpen, setIsBottomSheetOpen] = useState(true);
  const [inputCode, setInputCode] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [selectedDest, setSelectedDest] = useState<Destination | null>(null);
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const watchIdRef = useRef<number | null>(null);
  const simulationIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    if ("geolocation" in navigator) {
      const id = navigator.geolocation.watchPosition(
        (position) => {
          const newPoint = {
            lat: position.coords.latitude,
            lng: position.coords.longitude,
            timestamp: Date.now()
          };
          setUserPos(newPoint);
          if (role === UserRole.MESTRE && currentTrip?.isActive) {
            const updated = storageService.updateTripPath(currentTrip.code, newPoint);
            if (updated) setCurrentTrip({...updated});
          }
        },
        () => setError("Erro ao acessar GPS."),
        { enableHighAccuracy: true, timeout: 5000, maximumAge: 0 }
      );
      watchIdRef.current = id;
    }
    return () => { if (watchIdRef.current !== null) navigator.geolocation.clearWatch(watchIdRef.current); };
  }, [role, currentTrip]);

  useEffect(() => {
    if (role === UserRole.SEGUIDOR && currentTrip) {
      simulationIntervalRef.current = setInterval(() => {
        const trip = storageService.getTripByCode(currentTrip.code);
        if (trip) {
          setCurrentTrip({...trip});
          if (trip.path.length > 0) setMasterPos(trip.path[trip.path.length - 1]);
        }
      }, 3000);
    }
    return () => { if (simulationIntervalRef.current) clearInterval(simulationIntervalRef.current); };
  }, [role, currentTrip]);

  const handleSearchDestination = async () => {
    if (!searchQuery.trim()) return;
    setIsSearching(true);
    setError(null);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Encontre as coordenadas geográficas (latitude e longitude) para o local: "${searchQuery}". Forneça também um nome curto e legível para o local.`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              lat: { type: Type.NUMBER },
              lng: { type: Type.NUMBER },
              name: { type: Type.STRING }
            },
            required: ["lat", "lng", "name"]
          }
        }
      });
      const result = JSON.parse(response.text);
      setSelectedDest(result);
    } catch (err) {
      setError("Não foi possível encontrar o local. Tente clicar no mapa.");
    } finally {
      setIsSearching(false);
    }
  };

  const handleMapClick = (lat: number, lng: number) => {
    if (isConfiguringTrip) {
      setSelectedDest({ lat, lng, name: "Ponto no Mapa" });
    }
  };

  const handleStartTrip = () => {
    const code = Math.random().toString(36).substring(2, 8).toUpperCase();
    const newTrip: Trip = {
      id: Date.now().toString(),
      code,
      name: "Viagem em Grupo",
      masterId: "me",
      destination: selectedDest || undefined,
      path: userPos ? [userPos] : [],
      isActive: true,
      createdAt: Date.now()
    };
    storageService.saveTrip(newTrip);
    setCurrentTrip(newTrip);
    setRole(UserRole.MESTRE);
    setIsConfiguringTrip(false);
    setIsBottomSheetOpen(true);
  };

  const handleFollowMaster = () => {
    const trip = storageService.getTripByCode(inputCode);
    if (trip) {
      setCurrentTrip(trip);
      setRole(UserRole.SEGUIDOR);
      setIsBottomSheetOpen(true);
      setError(null);
    } else {
      setError("Código inválido.");
    }
  };

  if (role === UserRole.NONE && !isConfiguringTrip) {
    return (
      <div className="h-full w-full bg-slate-900 flex flex-col items-center justify-center p-6 text-white overflow-hidden">
        <div className="mb-12 text-center">
          <div className="bg-blue-600 w-20 h-20 rounded-2xl flex items-center justify-center mx-auto mb-4 shadow-xl">
            <Navigation size={40} className="text-white" />
          </div>
          <h1 className="text-4xl font-bold mb-2">Siga o Mestre</h1>
          <p className="text-slate-400">Comboio inteligente em tempo real.</p>
        </div>
        <div className="w-full max-w-sm space-y-4">
          <button onClick={() => setIsConfiguringTrip(true)} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-4 px-6 rounded-xl flex items-center justify-between transition-all">
            <div className="flex items-center"><Play size={20} className="mr-3"/> Ser o Mestre</div>
            <ChevronUp className="rotate-90 opacity-40" />
          </button>
          <div className="relative py-4">
            <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-slate-800"></div></div>
            <div className="relative flex justify-center text-xs uppercase"><span className="bg-slate-900 px-2 text-slate-500">Ou</span></div>
          </div>
          <input type="text" placeholder="Código da Viagem" className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-4 text-white uppercase" value={inputCode} onChange={(e) => setInputCode(e.target.value)} />
          <button onClick={handleFollowMaster} disabled={!inputCode} className="w-full bg-white text-slate-900 font-bold py-4 px-6 rounded-xl flex items-center justify-center disabled:opacity-50">
            <Users size={20} className="mr-2" /> Seguir um Mestre
          </button>
          {error && <p className="text-red-400 text-sm text-center">{error}</p>}
        </div>
      </div>
    );
  }

  if (isConfiguringTrip) {
    return (
      <div className="h-full w-full flex flex-col bg-white">
        <div className="p-4 bg-slate-900 text-white flex items-center justify-between">
          <button onClick={() => setIsConfiguringTrip(false)} className="text-slate-400">Voltar</button>
          <span className="font-bold">Configurar Destino</span>
          <div className="w-10"></div>
        </div>
        <div className="p-4 bg-slate-100 flex space-x-2">
          <div className="relative flex-1">
            <input 
              type="text" 
              placeholder="Para onde vamos?" 
              className="w-full pl-10 pr-4 py-3 rounded-xl border-none shadow-sm focus:ring-2 focus:ring-blue-500"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSearchDestination()}
            />
            <Search className="absolute left-3 top-3.5 text-slate-400" size={18} />
          </div>
          <button onClick={handleSearchDestination} className="bg-blue-600 text-white p-3 rounded-xl">
            {isSearching ? <Loader2 className="animate-spin" size={20} /> : <Search size={20} />}
          </button>
        </div>
        <div className="flex-1 relative">
          <MapComponent 
            userPos={userPos} 
            masterPos={null} 
            trip={selectedDest ? { destination: selectedDest, path: [] } as any : null} 
            role={UserRole.MESTRE}
            onMapClick={handleMapClick}
            isSelectingDestination={true}
          />
          {selectedDest && (
            <div className="absolute bottom-6 left-6 right-6 z-[1000] bg-white p-4 rounded-2xl shadow-2xl border border-blue-100">
              <div className="flex items-start space-x-3 mb-4">
                <MapPin className="text-blue-600 mt-1" size={20} />
                <div>
                  <div className="font-bold text-slate-900">Destino Selecionado:</div>
                  <div className="text-slate-500">{selectedDest.name}</div>
                </div>
              </div>
              <button onClick={handleStartTrip} className="w-full bg-blue-600 text-white font-bold py-4 rounded-xl shadow-lg shadow-blue-500/30">
                Iniciar Viagem do Comboio
              </button>
            </div>
          )}
          {!selectedDest && (
            <div className="absolute top-4 left-1/2 -translate-x-1/2 bg-slate-900/80 backdrop-blur text-white px-4 py-2 rounded-full text-xs font-bold pointer-events-none">
              Clique no mapa ou pesquise o local
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="h-full w-full relative">
      <div className="absolute inset-0">
        <MapComponent userPos={userPos} masterPos={masterPos} trip={currentTrip} role={role} />
      </div>

      <div className="absolute top-4 left-4 right-4 z-[500]">
        <div className="bg-white/95 backdrop-blur rounded-2xl p-4 shadow-xl flex items-center justify-between border border-white/50">
          <div className="flex items-center space-x-3">
            <div className={`${role === UserRole.MESTRE ? 'bg-blue-600' : 'bg-red-500'} w-10 h-10 rounded-full flex items-center justify-center text-white`}>
              {role === UserRole.MESTRE ? '👑' : '🚗'}
            </div>
            <div>
              <h2 className="font-bold text-slate-900 leading-tight">
                {role === UserRole.MESTRE ? 'Liderando' : 'Seguindo Mestre'}
              </h2>
              <div className="flex items-center text-[10px] text-green-600 font-bold uppercase tracking-wider mt-0.5">
                <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse mr-1"></div>
                Ao Vivo
              </div>
            </div>
          </div>
          <button onClick={() => { setRole(UserRole.NONE); setCurrentTrip(null); }} className="p-2 text-slate-400"><LogOut size={20} /></button>
        </div>
      </div>

      <div className={`absolute bottom-0 left-0 right-0 bg-white shadow-2xl rounded-t-3xl z-[1000] bottom-sheet border-t transition-transform ${isBottomSheetOpen ? 'translate-y-0' : 'translate-y-[calc(100%-70px)]'}`}>
        <div className="w-full flex flex-col items-center py-3 cursor-pointer" onClick={() => setIsBottomSheetOpen(!isBottomSheetOpen)}>
          <div className="w-12 h-1.5 bg-slate-200 rounded-full"></div>
        </div>

        <div className="px-6 pb-8 space-y-4">
          {currentTrip?.destination && (
            <div className="bg-slate-50 p-4 rounded-2xl flex items-center space-x-3 border border-slate-100">
              <div className="bg-green-100 p-2 rounded-lg text-green-600"><MapPin size={20} /></div>
              <div className="flex-1 min-w-0">
                <div className="text-xs text-slate-400 font-bold uppercase">Destino final</div>
                <div className="font-bold text-slate-900 truncate">{currentTrip.destination.name}</div>
              </div>
            </div>
          )}

          <div className="flex items-center justify-between bg-blue-50 p-4 rounded-2xl border border-blue-100">
            <div>
              <div className="text-xs text-blue-400 font-bold uppercase">Código do Grupo</div>
              <div className="text-2xl font-mono font-bold text-blue-600">{currentTrip?.code}</div>
            </div>
            <button onClick={() => { navigator.clipboard.writeText(currentTrip?.code || ''); setCopied(true); setTimeout(() => setCopied(false), 2000); }} className="bg-white p-3 rounded-xl shadow-sm text-blue-600 active:scale-95 transition-all">
              {copied ? <Check size={20} /> : <Copy size={20} />}
            </button>
          </div>

          <div className="grid grid-cols-2 gap-3 text-center">
            <div className="bg-slate-50 p-3 rounded-xl">
              <div className="text-[10px] text-slate-400 uppercase font-bold">Rastro</div>
              <div className="font-bold">{currentTrip?.path.length} pts</div>
            </div>
            <div className="bg-slate-50 p-3 rounded-xl">
