          <button onClick={handleFollowMaster} disabled={!inputCode} className="w-full bg-white text-slate-900 font-bold py-5 px-6 rounded-2xl flex items-center justify-center shadow-lg active:scale-95 transition-all disabled:opacity-50">
            <Users size={24} className="mr-3" /> Seguir um Mestre
          </button>
          {error && <p className="text-red-400 text-sm text-center font-medium">{error}</p>}
        </div>
      </div>
    );
  }

  if (isConfiguringTrip) {
    return (
      <div className="h-full w-full flex flex-col bg-white">
        <div className="p-5 bg-slate-900 text-white flex items-center justify-between shadow-lg">
          <button onClick={() => setIsConfiguringTrip(false)} className="text-slate-400 font-bold">Cancelar</button>
          <span className="font-bold text-lg">Definir Destino</span>
          <div className="w-10"></div>
        </div>
        <div className="p-4 bg-slate-100 flex space-x-2">
          <div className="relative flex-1">
            <input 
              type="text" 
              placeholder="Digite o nome do local..." 
              className="w-full pl-11 pr-4 py-4 rounded-2xl border-none shadow-sm focus:ring-2 focus:ring-blue-500"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSearchDestination()}
            />
            <Search className="absolute left-4 top-4.5 text-slate-400" size={20} />
          </div>
          <button onClick={handleSearchDestination} className="bg-blue-600 text-white px-5 rounded-2xl shadow-lg active:scale-95 transition-all">
            {isSearching ? <Loader2 className="animate-spin" size={24} /> : <Search size={24} />}
          </button>
        </div>
        <div className="flex-1 relative">
          <MapComponent 
            userPos={userPos} 
            masterPos={null} 
            trip={selectedDest ? { destination: selectedDest, path: [] } as any : null} 
            role={UserRole.MESTRE}
            onMapClick={(lat, lng) => setSelectedDest({ lat, lng, name: "Local selecionado no mapa" })}
            isSelectingDestination={true}
          />
          {selectedDest && (
            <div className="absolute bottom-8 left-6 right-6 z-[1000] bg-white p-6 rounded-3xl shadow-2xl border border-blue-50 animate-in slide-in-from-bottom duration-300">
              <div className="flex items-start space-x-4 mb-5">
                <div className="bg-blue-50 p-3 rounded-2xl"><MapPin className="text-blue-600" size={24} /></div>
                <div className="flex-1">
                  <div className="text-sm font-bold text-blue-600 uppercase tracking-tight">Destino Confirmado</div>
                  <div className="text-slate-900 font-extrabold text-lg line-clamp-2 leading-tight">{selectedDest.name}</div>
                </div>
              </div>
              <button onClick={handleStartTrip} className="w-full bg-blue-600 text-white font-extrabold py-5 rounded-2xl shadow-xl shadow-blue-500/30 active:scale-95 transition-all flex items-center justify-center">
                <Navigation size={20} className="mr-2" /> Iniciar Comboio Agora
              </button>
            </div>
          )}
          {!selectedDest && (
            <div className="absolute top-6 left-1/2 -translate-x-1/2 bg-slate-900/90 backdrop-blur-md text-white px-6 py-3 rounded-full text-sm font-bold shadow-2xl flex items-center">
              <Target size={16} className="mr-2 text-blue-400" /> Toque no mapa para marcar destino
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="h-full w-full relative overflow-hidden bg-slate-100">
      <div className="absolute inset-0">
        <MapComponent userPos={userPos} masterPos={masterPos} trip={currentTrip} role={role} />
      </div>

      {/* Header com Status do GPS */}
      <div className="absolute top-6 left-4 right-4 z-[500]">
        <div className="bg-white/95 backdrop-blur-md rounded-2xl p-4 shadow-2xl flex items-center justify-between border border-white/40">
          <div className="flex items-center space-x-3">
            <div className={`${role === UserRole.MESTRE ? 'bg-blue-600' : 'bg-red-500'} w-12 h-12 rounded-2xl flex items-center justify-center text-white shadow-lg`}>
              {role === UserRole.MESTRE ? '👑' : '🚗'}
            </div>
            <div>
              <h2 className="font-extrabold text-slate-900 text-lg leading-none">
                {role === UserRole.MESTRE ? 'Você é o Mestre' : 'Seguindo Mestre'}
              </h2>
              <div className="flex items-center text-[10px] text-green-600 font-black uppercase tracking-widest mt-1.5">
                <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse mr-2"></div>
                Transmissão Ativa
