import React, { useEffect, useRef } from 'react';
import { MapContainer, TileLayer, Marker, Polyline, useMap, ZoomControl, useMapEvents } from 'react-leaflet';
import L from 'leaflet';
import { Trip, GeoPoint, UserRole, Destination } from '../types';

interface MapProps {
  userPos: GeoPoint | null;
  masterPos: GeoPoint | null;
  trip: Trip | null;
  role: UserRole;
  onMapClick?: (lat: number, lng: number) => void;
  isSelectingDestination?: boolean;
}

const RecenterMap: React.FC<{ pos: GeoPoint | null; destination: Destination | undefined }> = ({ pos, destination }) => {
  const map = useMap();
  const hasInitializedRef = useRef(false);

  useEffect(() => {
    if (!hasInitializedRef.current && pos && destination) {
      // No início da viagem, foca nos dois pontos
      const bounds = L.latLngBounds([pos.lat, pos.lng], [destination.lat, destination.lng]);
      map.fitBounds(bounds, { padding: [100, 100], maxZoom: 15 });
      hasInitializedRef.current = true;
    } else if (pos && !destination) {
      map.setView([pos.lat, pos.lng], map.getZoom());
    }
  }, [pos, destination, map]);

  return null;
};

const MapEvents: React.FC<{ onClick: (lat: number, lng: number) => void }> = ({ onClick }) => {
  useMapEvents({
    click: (e) => onClick(e.latlng.lat, e.latlng.lng),
  });
  return null;
};

const MapComponent: React.FC<MapProps> = ({ userPos, masterPos, trip, role, onMapClick, isSelectingDestination }) => {
  const masterIcon = L.divIcon({
    className: 'custom-marker-master',
    html: '<div style="width: 24px; height: 24px; display: flex; align-items: center; justify-content: center; font-size: 16px;">👑</div>',
    iconSize: [32, 32],
    iconAnchor: [16, 16]
  });

  const followerIcon = L.divIcon({
    className: 'custom-marker-follower',
    html: '<div style="width: 24px; height: 24px; display: flex; align-items: center; justify-content: center; font-size: 16px;">🚗</div>',
    iconSize: [32, 32],
    iconAnchor: [16, 16]
  });

  const destIcon = L.divIcon({
    className: 'bg-slate-900 border-4 border-white rounded-2xl shadow-2xl flex items-center justify-center',
    html: '<div style="width: 32px; height: 32px; display: flex; align-items: center; justify-content: center; font-size: 18px;">🏁</div>',
    iconSize: [40, 40],
    iconAnchor: [20, 40]
  });

  const polylinePositions = trip?.path.map(p => [p.lat, p.lng] as [number, number]) || [];

  // Linha de guia reforçada
  const guideLine = (userPos && trip?.destination) 
    ? [[userPos.lat, userPos.lng], [trip.destination.lat, trip.destination.lng]] as [number, number][]
    : [];

  return (
    <div className="w-full h-full relative">
      <MapContainer
        center={userPos ? [userPos.lat, userPos.lng] : [-23.5505, -46.6333]}
        zoom={16}
        scrollWheelZoom={true}
        className="w-full h-full grayscale-[0.2]"
        zoomControl={false}
      >
        <TileLayer
          attribution='&copy; OpenStreetMap'
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />
        <ZoomControl position="topright" />

        {isSelectingDestination && onMapClick && <MapEvents onClick={onMapClick} />}

        {/* Rastro percorrido - Linha Sólida Azul */}
        {polylinePositions.length > 1 && (
          <Polyline 
            positions={polylinePositions} 
            color="#2563eb" 
            weight={7} 
            opacity={0.8} 
            lineJoin="round" 
            lineCap="round"
          />
        )}

        {/* Linha de guia para o destino - Linha Pontilhada Esmeralda */}
        {guideLine.length > 0 && (
          <Polyline 
            positions={guideLine} 
            color="#10b981" 
            weight={4} 
            dashArray="10, 15" 
            opacity={0.6} 
          />
        )}

        {/* Destino Final */}
        {trip?.destination && (
          <Marker position={[trip.destination.lat, trip.destination.lng]} icon={destIcon} />
        )}

        {/* Usuário Atual */}
        {userPos && (
          <Marker 
            position={[userPos.lat, userPos.lng]} 
            icon={role === UserRole.MESTRE ? masterIcon : followerIcon} 
            zIndexOffset={1000}
          />
        )}

        {/* Mestre (visto pelo seguidor) */}
        {role === UserRole.SEGUIDOR && masterPos && (
          <Marker 
            position={[masterPos.lat, masterPos.lng]} 
            icon={masterIcon} 
            zIndexOffset={900}
          />
        )}

        {!isSelectingDestination && <RecenterMap pos={userPos} destination={trip?.destination} />}
      </MapContainer>
    </div>
  );
};

export default MapComponent;

export interface GeoPoint {
  lat: number;
  lng: number;
  timestamp: number;
}

export interface Destination {
  lat: number;
  lng: number;
  name: string;
}

export enum UserRole {
  MESTRE = 'MESTRE',
  SEGUIDOR = 'SEGUIDOR',
  NONE = 'NONE'
}

export interface Trip {
  id: string;
  code: string;
  name: string;
  masterId: string;
  destination?: Destination;
  plannedRoute?: [number, number][]; // Polilinha do caminho real pelas ruas
  path: GeoPoint[];
  isActive: boolean;
  createdAt: number;
}

export interface AppState {
  role: UserRole;
  currentTrip: Trip | null;
  userPosition: GeoPoint | null;
  masterPosition: GeoPoint | null;
}

import React, { useEffect, useRef } from 'react';
import { MapContainer, TileLayer, Marker, Polyline, useMap, ZoomControl, useMapEvents } from 'react-leaflet';
import L from 'leaflet';
import { Trip, GeoPoint, UserRole, Destination } from '../types';

interface MapProps {
  userPos: GeoPoint | null;
  masterPos: GeoPoint | null;
  trip: Trip | null;
  role: UserRole;
  onMapClick?: (lat: number, lng: number) => void;
  isSelectingDestination?: boolean;
}

const MapController: React.FC<{ pos: GeoPoint | null; destination: Destination | undefined; plannedRoute?: [number, number][] }> = ({ pos, destination, plannedRoute }) => {
  const map = useMap();

  // Força o mapa a preencher o container corretamente (evita o cinza)
  useEffect(() => {
    setTimeout(() => {
      map.invalidateSize();
    }, 100);
  }, [map]);

  useEffect(() => {
    if (plannedRoute && plannedRoute.length > 0) {
      const bounds = L.latLngBounds(plannedRoute);
      map.fitBounds(bounds, { padding: [50, 50], maxZoom: 15 });
    } else if (pos && destination) {
      const bounds = L.latLngBounds([pos.lat, pos.lng], [destination.lat, destination.lng]);
      map.fitBounds(bounds, { padding: [80, 80], maxZoom: 15 });
    } else if (pos) {
      map.setView([pos.lat, pos.lng], map.getZoom());
    }
  }, [pos, destination, plannedRoute, map]);

  return null;
};

const MapEvents: React.FC<{ onClick: (lat: number, lng: number) => void }> = ({ onClick }) => {
  useMapEvents({
    click: (e) => onClick(e.latlng.lat, e.latlng.lng),
  });
  return null;
};

const MapComponent: React.FC<MapProps> = ({ userPos, masterPos, trip, role, onMapClick, isSelectingDestination }) => {
  const masterIcon = L.divIcon({
    className: 'custom-marker-master',
    html: '<div style="width: 24px; height: 24px; display: flex; align-items: center; justify-content: center; font-size: 16px;">👑</div>',
    iconSize: [32, 32],
    iconAnchor: [16, 16]
  });

  const followerIcon = L.divIcon({
    className: 'custom-marker-follower',
    html: '<div style="width: 24px; height: 24px; display: flex; align-items: center; justify-content: center; font-size: 16px;">🚗</div>',
    iconSize: [32, 32],
    iconAnchor: [16, 16]
  });

  const destIcon = L.divIcon({
    className: 'bg-slate-900 border-4 border-white rounded-2xl shadow-2xl flex items-center justify-center',
    html: '<div style="width: 32px; height: 32px; display: flex; align-items: center; justify-content: center; font-size: 18px;">🏁</div>',
    iconSize: [40, 40],
    iconAnchor: [20, 40]
  });

  const recordedPath = trip?.path.map(p => [p.lat, p.lng] as [number, number]) || [];

  return (
    <div className="w-full h-full flex flex-col">
      <MapContainer
        center={userPos ? [userPos.lat, userPos.lng] : [-23.5505, -46.6333]}
        zoom={16}
        scrollWheelZoom={true}
        className="flex-grow w-full h-full"
        zoomControl={false}
      >
        <TileLayer
          attribution='&copy; OpenStreetMap'
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />
        <ZoomControl position="topright" />

        {isSelectingDestination && onMapClick && <MapEvents onClick={onMapClick} />}

        {/* Rota Planejada (Caminho Uber - Azul Marinho) */}
        {trip?.plannedRoute && trip.plannedRoute.length > 0 && (
          <Polyline 
            positions={trip.plannedRoute} 
            color="#1e40af" 
            weight={6} 
            opacity={0.9} 
            lineJoin="round"
          />
        )}

        {/* Rastro Realmente Percorrido (Caminho Ativo - Azul Claro) */}
        {recordedPath.length > 1 && (
          <Polyline 
            positions={recordedPath} 
            color="#3b82f6" 
            weight={8} 
            opacity={0.6} 
            lineJoin="round" 
            lineCap="round"
          />
        )}

        {/* Destino Final */}
        {trip?.destination && (
          <Marker position={[trip.destination.lat, trip.destination.lng]} icon={destIcon} />
        )}

        {/* Usuário Atual */}
        {userPos && (
          <Marker 
            position={[userPos.lat, userPos.lng]} 
            icon={role === UserRole.MESTRE ? masterIcon : followerIcon} 
            zIndexOffset={1000}
          />
        )}

        {/* Mestre (visto pelo seguidor) */}
        {role === UserRole.SEGUIDOR && masterPos && (
          <Marker 
            position={[masterPos.lat, masterPos.lng]} 
            icon={masterIcon} 
            zIndexOffset={900}
          />
        )}

        {!isSelectingDestination && <MapController pos={userPos} destination={trip?.destination} plannedRoute={trip?.plannedRoute} />}
      </MapContainer>
    </div>
  );
};

export default MapComponent;

import React, { useState, useEffect, useRef } from 'react';
import { UserRole, Trip, GeoPoint, Destination } from './types';
import MapComponent from './components/MapComponent';
import { storageService } from './services/storage';
import { Navigation, Play, StopCircle, Share2, Users, MapPin, ChevronUp, ChevronDown, Copy, Check, LogOut, Search, Map as MapIcon, Loader2, Target, ArrowLeft } from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";

// Haversine para filtrar rastro parado
const calculateDistance = (p1: GeoPoint, p2: GeoPoint) => {
  const R = 6371e3;
  const φ1 = p1.lat * Math.PI / 180;
  const φ2 = p2.lat * Math.PI / 180;
  const Δφ = (p2.lat - p1.lat) * Math.PI / 180;
  const Δλ = (p2.lng - p1.lng) * Math.PI / 180;
  const a = Math.sin(Δφ / 2) * Math.sin(Δφ / 2) + Math.cos(φ1) * Math.cos(φ2) * Math.sin(Δλ / 2) * Math.sin(Δλ / 2);
  return R * (2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a)));
};

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole>(UserRole.NONE);
  const [isConfiguringTrip, setIsConfiguringTrip] = useState(false);
  const [currentTrip, setCurrentTrip] = useState<Trip | null>(null);
  const [userPos, setUserPos] = useState<GeoPoint | null>(null);
  const [masterPos, setMasterPos] = useState<GeoPoint | null>(null);
  const [isBottomSheetOpen, setIsBottomSheetOpen] = useState(true);
  const [inputCode, setInputCode] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [selectedDest, setSelectedDest] = useState<Destination | null>(null);
  const [plannedRoute, setPlannedRoute] = useState<[number, number][]>([]);
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const watchIdRef = useRef<number | null>(null);
  const simulationIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const lastRecordedPosRef = useRef<GeoPoint | null>(null);

  // Busca rota real pelas ruas (OSRM)
  const fetchRoadRoute = async (start: GeoPoint, end: Destination) => {
    try {
      const response = await fetch(`https://router.project-osrm.org/route/v1/driving/${start.lng},${start.lat};${end.lng},${end.lat}?overview=full&geometries=geojson`);
      const data = await response.json();
      if (data.routes && data.routes.length > 0) {
        // OSRM retorna [lng, lat], precisamos converter para [lat, lng]
        return data.routes[0].geometry.coordinates.map((coord: [number, number]) => [coord[1], coord[0]]);
      }
    } catch (e) {
      console.error("Erro ao buscar rota OSRM", e);
    }
    return [];
  };

  useEffect(() => {
    if ("geolocation" in navigator) {
      const id = navigator.geolocation.watchPosition(
        (position) => {
          const newPoint: GeoPoint = {
            lat: position.coords.latitude,
            lng: position.coords.longitude,
            timestamp: Date.now()
          };
          setUserPos(newPoint);

          if (role === UserRole.MESTRE && currentTrip?.isActive) {
            const distanceMoved = lastRecordedPosRef.current ? calculateDistance(lastRecordedPosRef.current, newPoint) : Infinity;
            if (distanceMoved > 5) {
              const updated = storageService.updateTripPath(currentTrip.code, newPoint);
              if (updated) {
                setCurrentTrip({...updated});
                lastRecordedPosRef.current = newPoint;
              }
            }
          }
        },
        () => setError("GPS inacessível."),
        { enableHighAccuracy: true, timeout: 5000, maximumAge: 0 }
      );
      watchIdRef.current = id;
    }
    return () => { if (watchIdRef.current !== null) navigator.geolocation.clearWatch(watchIdRef.current); };
  }, [role, currentTrip]);

  useEffect(() => {
    if (role === UserRole.SEGUIDOR && currentTrip) {
      simulationIntervalRef.current = setInterval(() => {
        const trip = storageService.getTripByCode(currentTrip.code);
        if (trip) {
          setCurrentTrip({...trip});
          if (trip.path.length > 0) setMasterPos(trip.path[trip.path.length - 1]);
        }
      }, 3000);
    }
    return () => { if (simulationIntervalRef.current) clearInterval(simulationIntervalRef.current); };
  }, [role, currentTrip]);

  // Atualiza rota visual ao selecionar destino
  useEffect(() => {
    if (selectedDest && userPos) {
      fetchRoadRoute(userPos, selectedDest).then(route => setPlannedRoute(route));
    }
  }, [selectedDest, userPos]);

  const handleSearchDestination = async () => {
    if (!searchQuery.trim()) return;
    setIsSearching(true);
    setError(null);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Localize o ponto mais provável para: "${searchQuery}". Retorne as coordenadas.`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              lat: { type: Type.NUMBER },
              lng: { type: Type.NUMBER },
              name: { type: Type.STRING }
            },
            required: ["lat", "lng", "name"]
          }
        }
      });
      const result = JSON.parse(response.text);
      setSelectedDest(result);
    } catch (err) {
      setError("Local não encontrado.");
    } finally {
      setIsSearching(false);
    }
  };

  const handleStartTrip = () => {
    const code = Math.random().toString(36).substring(2, 8).toUpperCase();
    const newTrip: Trip = {
      id: Date.now().toString(),
      code,
      name: "Viagem em Grupo",
      masterId: "me",
      destination: selectedDest || undefined,
      plannedRoute: plannedRoute,
      path: userPos ? [userPos] : [],
      isActive: true,
      createdAt: Date.now()
    };
    storageService.saveTrip(newTrip);
    setCurrentTrip(newTrip);
    lastRecordedPosRef.current = userPos;
    setRole(UserRole.MESTRE);
    setIsConfiguringTrip(false);
    setIsBottomSheetOpen(true);
  };

  if (role === UserRole.NONE && !isConfiguringTrip) {
    return (
      <div className="h-full w-full bg-slate-900 flex flex-col items-center justify-center p-6 text-white">
        <div className="mb-12 text-center">
          <div className="bg-blue-600 w-20 h-20 rounded-3xl flex items-center justify-center mx-auto mb-6 shadow-2xl">
            <Navigation size={40} className="text-white" />
          </div>
          <h1 className="text-4xl font-extrabold mb-3 tracking-tight">Siga o Mestre</h1>
          <p className="text-slate-400">Comboio inteligente para viagens em grupo.</p>
        </div>
        <div className="w-full max-w-sm space-y-4">
          <button onClick={() => setIsConfiguringTrip(true)} className="w-full bg-blue-600 text-white font-bold py-5 px-6 rounded-2xl flex items-center justify-between transition-all">
            <div className="flex items-center"><Play size={24} className="mr-4 fill-white"/> Ser o Mestre</div>
            <ChevronUp className="rotate-90 opacity-40" />
          </button>
          <div className="relative py-6">
            <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-slate-800"></div></div>
            <div className="relative flex justify-center text-xs uppercase"><span className="bg-slate-900 px-4 text-slate-500 font-bold">OU</span></div>
          </div>
          <input type="text" placeholder="Código de 6 dígitos" className="w-full bg-slate-800 border border-slate-700 rounded-2xl px-5 py-5 text-white uppercase text-center text-xl font-mono tracking-widest" value={inputCode} onChange={(e) => setInputCode(e.target.value)} />
          <button onClick={() => { const trip = storageService.getTripByCode(inputCode); if(trip){ setCurrentTrip(trip); setRole(UserRole.SEGUIDOR); }else{ setError("Código inválido."); } }} disabled={!inputCode} className="w-full bg-white text-slate-900 font-bold py-5 px-6 rounded-2xl flex items-center justify-center disabled:opacity-50">
            <Users size={24} className="mr-3" /> Seguir um Mestre
          </button>
        </div>
      </div>
    );
  }

  if (isConfiguringTrip) {
    return (
      <div className="fixed inset-0 flex flex-col bg-white z-[2000]">
        {/* Header Superior */}
        <div className="p-4 bg-slate-900 text-white flex items-center justify-between z-10">
          <button onClick={() => setIsConfiguringTrip(false)} className="flex items-center text-slate-400">
            <ArrowLeft className="mr-2" size={20} /> Cancelar
          </button>
          <span className="font-bold text-lg">Definir Destino</span>
          <div className="w-10"></div>
        </div>

        {/* Barra de Pesquisa Flutuante */}
        <div className="absolute top-20 left-4 right-4 z-20 flex space-x-2">
          <div className="relative flex-1 shadow-2xl">
            <input 
              type="text" 
              placeholder="Digite o endereço de destino..." 
              className="w-full pl-11 pr-4 py-4 rounded-2xl border-none focus:ring-2 focus:ring-blue-500 text-slate-900"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSearchDestination()}
            />
            <Search className="absolute left-4 top-4.5 text-slate-400" size={20} />
          </div>
          <button onClick={handleSearchDestination} className="bg-blue-600 text-white px-5 rounded-2xl shadow-xl active:scale-95 transition-all">
            {isSearching ? <Loader2 className="animate-spin" size={24} /> : <Search size={24} />}
          </button>
        </div>

        {/* Mapa em Tela Cheia */}
        <div className="flex-grow relative h-full w-full">
          <MapComponent 
            userPos={userPos} 
            masterPos={null} 
            trip={selectedDest ? { destination: selectedDest, plannedRoute: plannedRoute, path: [] } as any : null} 
            role={UserRole.MESTRE}
            onMapClick={(lat, lng) => {
              setSelectedDest({ lat, lng, name: "Local selecionado" });
            }}
            isSelectingDestination={true}
          />

          {/* Card de Confirmação (Estilo Uber) */}
          {selectedDest && (
            <div className="absolute bottom-10 left-6 right-6 z-20 bg-white p-6 rounded-3xl shadow-[0_20px_60px_rgba(0,0,0,0.3)] border border-slate-100 animate-in slide-in-from-bottom duration-300">
              <div className="flex items-start space-x-4 mb-6">
                <div className="bg-blue-100 p-3 rounded-2xl"><MapPin className="text-blue-600" size={28} /></div>
                <div className="flex-1">
                  <div className="text-[10px] font-black text-blue-600 uppercase tracking-widest mb-1">Destino Encontrado</div>
                  <div className="text-slate-900 font-extrabold text-xl leading-tight line-clamp-2">{selectedDest.name}</div>
                </div>
              </div>
              <button onClick={handleStartTrip} className="w-full bg-slate-900 text-white font-black py-5 rounded-2xl shadow-xl active:scale-95 transition-all flex items-center justify-center text-lg">
                <Navigation size={22} className="mr-3 text-blue-400" /> Iniciar Comboio
              </button>
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="h-full w-full relative overflow-hidden">
      <div className="absolute inset-0">
        <MapComponent userPos={userPos} masterPos={masterPos} trip={currentTrip} role={role} />
      </div>

      {/* Header Overlay */}
      <div className="absolute top-6 left-4 right-4 z-[500]">
        <div className="bg-white/95 backdrop-blur-md rounded-2xl p-4 shadow-2xl flex items-center justify-between border border-white/50">
          <div className="flex items-center space-x-3">
            <div className={`${role === UserRole.MESTRE ? 'bg-blue-600' : 'bg-red-500'} w-12 h-12 rounded-2xl flex items-center justify-center text-white shadow-lg`}>
              {role === UserRole.MESTRE ? '👑' : '🚗'}
            </div>
            <div>
              <h2 className="font-extrabold text-slate-900 text-lg leading-none">
                {role === UserRole.MESTRE ? 'Liderando Comboio' : 'Seguindo Mestre'}
              </h2>
              <div className="flex items-center text-[10px] text-green-600 font-black uppercase tracking-widest mt-1.5">
                <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse mr-2"></div> AO VIVO
              </div>
            </div>
          </div>
          <button onClick={() => { setRole(UserRole.NONE); setCurrentTrip(null); }} className="p-3 text-slate-400 hover:text-red-500 transition-colors bg-slate-50 rounded-xl">
            <LogOut size={22} />
          </button>
        </div>
      </div>

      {/* Bottom UI Sheet */}
      <div className={`absolute bottom-0 left-0 right-0 bg-white shadow-[0_-20px_50px_rgba(0,0,0,0.1)] rounded-t-[40px] z-[1000] bottom-sheet border-t border-slate-50 transition-transform duration-500 ${isBottomSheetOpen ? 'translate-y-0' : 'translate-y-[calc(100%-80px)]'}`}>
        <div className="w-full flex flex-col items-center py-4 cursor-pointer" onClick={() => setIsBottomSheetOpen(!isBottomSheetOpen)}>
          <div className="w-16 h-1.5 bg-slate-200 rounded-full"></div>
        </div>

        <div className="px-6 pb-10 space-y-6">
          {currentTrip?.destination && (
            <div className="bg-slate-50 p-5 rounded-3xl flex items-center space-x-4 border border-slate-100">
              <div className="bg-green-100 p-3 rounded-2xl text-green-600"><MapPin size={24} /></div>
              <div className="flex-1 min-w-0">
                <div className="text-[10px] text-slate-400 font-black uppercase tracking-widest mb-1">Destino Final</div>
                <div className="font-extrabold text-slate-900 truncate text-lg">{currentTrip.destination.name}</div>
              </div>
            </div>
          )}

          <div className="flex items-center justify-between bg-blue-50 p-5 rounded-3xl border border-blue-100/50">
            <div>
              <div className="text-[10px] text-blue-400 font-black uppercase tracking-widest mb-1">Código do Grupo</div>
              <div className="text-3xl font-mono font-black text-blue-600 tracking-tighter">{currentTrip?.code}</div>
            </div>
            <button onClick={() => { navigator.clipboard.writeText(currentTrip?.code || ''); setCopied(true); setTimeout(() => setCopied(false), 2000); }} className="bg-white p-4 rounded-2xl shadow-sm text-blue-600 active:scale-90 transition-all border border-blue-100">
              {copied ? <Check size={24} className="text-green-500" /> : <Copy size={24} />}
            </button>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100 text-center">
              <div className="text-[10px] text-slate-400 uppercase font-black tracking-widest mb-1">Pontos GPS</div>
              <div className="font-black text-xl text-slate-800">{currentTrip?.path.length}</div>
            </div>
            <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100 text-center">
              <div className="text-[10px] text-slate-400 uppercase font-black tracking-widest mb-1">Iniciado às</div>
              <div className="font-black text-xl text-slate-800">{new Date(currentTrip?.createdAt || 0).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</div>
            </div>
          </div>

          {role === UserRole.MESTRE && currentTrip?.isActive && (
            <button onClick={() => { if(currentTrip) storageService.saveTrip({...currentTrip, isActive: false}); setCurrentTrip(prev => prev ? {...prev, isActive: false} : null); }} className="w-full bg-red-500 text-white font-black py-5 rounded-3xl shadow-2xl shadow-red-200 active:scale-95 transition-all text-lg">
              Encerrar Viagem
            </button>
          )}

          <button className="w-full border-2 border-slate-100 py-4 rounded-3xl font-bold text-slate-500 flex items-center justify-center hover:bg-slate-50 transition-colors">
            <Share2 className="mr-3" size={20} /> Convidar via WhatsApp
          </button>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useEffect, useRef } from 'react';
import { MapContainer, TileLayer, Marker, Polyline, useMap, ZoomControl, useMapEvents } from 'react-leaflet';
import L from 'leaflet';
import { Trip, GeoPoint, UserRole, Destination } from '../types';

interface MapProps {
  userPos: GeoPoint | null;
  masterPos: GeoPoint | null;
  trip: Trip | null;
  role: UserRole;
  onMapClick?: (lat: number, lng: number) => void;
  isSelectingDestination?: boolean;
}

const MapController: React.FC<{ pos: GeoPoint | null; destination: Destination | undefined; plannedRoute?: [number, number][] }> = ({ pos, destination, plannedRoute }) => {
  const map = useMap();
  const initialFitRef = useRef(false);

  // Força o redimensionamento do mapa para evitar áreas cinzas
  useEffect(() => {
    const timer = setTimeout(() => {
      map.invalidateSize();
    }, 250);
    return () => clearTimeout(timer);
  }, [map]);

  // Ajusta o enquadramento (Fit Bounds)
  useEffect(() => {
    if (plannedRoute && plannedRoute.length > 0 && !initialFitRef.current) {
      const bounds = L.latLngBounds(plannedRoute);
      map.fitBounds(bounds, { padding: [70, 70], maxZoom: 16 });
      initialFitRef.current = true;
    } else if (pos && !initialFitRef.current) {
      map.setView([pos.lat, pos.lng], 16);
      initialFitRef.current = true;
    }
  }, [plannedRoute, pos, map]);

  // Se o usuário se mover e estivermos em modo "Follow", centraliza suavemente
  useEffect(() => {
    if (pos && initialFitRef.current) {
      // Opcional: só centralizar se o usuário sair muito do centro
      // map.panTo([pos.lat, pos.lng]);
    }
  }, [pos, map]);

  return null;
};

const MapEvents: React.FC<{ onClick: (lat: number, lng: number) => void }> = ({ onClick }) => {
  useMapEvents({
    click: (e) => onClick(e.latlng.lat, e.latlng.lng),
  });
  return null;
};

const MapComponent: React.FC<MapProps> = ({ userPos, masterPos, trip, role, onMapClick, isSelectingDestination }) => {
  const masterIcon = L.divIcon({
    className: 'bg-blue-600 border-4 border-white rounded-full shadow-lg flex items-center justify-center',
    html: '<div style="font-size: 14px;">👑</div>',
    iconSize: [32, 32],
    iconAnchor: [16, 16]
  });

  const followerIcon = L.divIcon({
    className: 'bg-red-500 border-4 border-white rounded-full shadow-lg flex items-center justify-center',
    html: '<div style="font-size: 14px;">🚗</div>',
    iconSize: [32, 32],
    iconAnchor: [16, 16]
  });

  const destIcon = L.divIcon({
    className: 'bg-slate-900 border-4 border-white rounded-xl shadow-2xl flex items-center justify-center',
    html: '<div style="font-size: 16px;">🏁</div>',
    iconSize: [36, 36],
    iconAnchor: [18, 36]
  });

  const recordedPath = trip?.path.map(p => [p.lat, p.lng] as [number, number]) || [];

  return (
    <div className="absolute inset-0 w-full h-full">
      <MapContainer
        center={userPos ? [userPos.lat, userPos.lng] : [-23.5505, -46.6333]}
        zoom={16}
        zoomControl={false}
        className="w-full h-full"
      >
        <TileLayer
          attribution='&copy; OpenStreetMap contributors'
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />
        <ZoomControl position="bottomright" />

        {isSelectingDestination && onMapClick && <MapEvents onClick={onMapClick} />}

        {/* Rota Planejada (Caminho estilo Uber) */}
        {trip?.plannedRoute && trip.plannedRoute.length > 0 && (
          <Polyline 
            positions={trip.plannedRoute} 
            color="#2563eb" 
            weight={6} 
            opacity={0.8} 
            lineJoin="round"
          />
        )}

        {/* Rastro percorrido */}
        {recordedPath.length > 1 && (
          <Polyline 
            positions={recordedPath} 
            color="#10b981" 
            weight={8} 
            opacity={0.5} 
            lineJoin="round" 
            lineCap="round"
          />
        )}

        {/* Destino */}
        {trip?.destination && (
          <Marker position={[trip.destination.lat, trip.destination.lng]} icon={destIcon} />
        )}

        {/* Usuário Atual */}
        {userPos && (
          <Marker 
            position={[userPos.lat, userPos.lng]} 
            icon={role === UserRole.MESTRE ? masterIcon : followerIcon} 
            zIndexOffset={1000}
          />
        )}

        {/* Mestre (visível para seguidor) */}
        {role === UserRole.SEGUIDOR && masterPos && (
          <Marker 
            position={[masterPos.lat, masterPos.lng]} 
            icon={masterIcon} 
            zIndexOffset={900}
          />
        )}

        <MapController pos={userPos} destination={trip?.destination} plannedRoute={trip?.plannedRoute} />
      </MapContainer>
    </div>
  );
};

export default MapComponent;

import React, { useState, useEffect, useRef } from 'react';
import { UserRole, Trip, GeoPoint, Destination } from './types';
import MapComponent from './components/MapComponent';
import { storageService } from './services/storage';
import { Navigation, Play, StopCircle, Share2, Users, MapPin, ChevronUp, ChevronDown, Copy, Check, LogOut, Search, Map as MapIcon, Loader2, Target, ArrowLeft } from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";

const calculateDistance = (p1: GeoPoint, p2: GeoPoint) => {
  const R = 6371e3;
  const φ1 = p1.lat * Math.PI / 180;
  const φ2 = p2.lat * Math.PI / 180;
  const Δφ = (p2.lat - p1.lat) * Math.PI / 180;
  const Δλ = (p2.lng - p1.lng) * Math.PI / 180;
  const a = Math.sin(Δφ / 2) * Math.sin(Δφ / 2) + Math.cos(φ1) * Math.cos(φ2) * Math.sin(Δλ / 2) * Math.sin(Δλ / 2);
  return R * (2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a)));
};

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole>(UserRole.NONE);
  const [isConfiguringTrip, setIsConfiguringTrip] = useState(false);
  const [currentTrip, setCurrentTrip] = useState<Trip | null>(null);
  const [userPos, setUserPos] = useState<GeoPoint | null>(null);
  const [masterPos, setMasterPos] = useState<GeoPoint | null>(null);
  const [isBottomSheetOpen, setIsBottomSheetOpen] = useState(true);
  const [inputCode, setInputCode] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [selectedDest, setSelectedDest] = useState<Destination | null>(null);
  const [plannedRoute, setPlannedRoute] = useState<[number, number][]>([]);
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const watchIdRef = useRef<number | null>(null);
  const simulationIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const lastRecordedPosRef = useRef<GeoPoint | null>(null);

  const fetchRoadRoute = async (start: GeoPoint, end: Destination) => {
    try {
      const response = await fetch(`https://router.project-osrm.org/route/v1/driving/${start.lng},${start.lat};${end.lng},${end.lat}?overview=full&geometries=geojson`);
      const data = await response.json();
      if (data.routes && data.routes.length > 0) {
        return data.routes[0].geometry.coordinates.map((coord: [number, number]) => [coord[1], coord[0]]);
      }
    } catch (e) {
      console.error("Erro OSRM", e);
    }
    return [];
  };

  useEffect(() => {
    if ("geolocation" in navigator) {
      const id = navigator.geolocation.watchPosition(
        (position) => {
          const newPoint: GeoPoint = {
            lat: position.coords.latitude,
            lng: position.coords.longitude,
            timestamp: Date.now()
          };
          setUserPos(newPoint);

          if (role === UserRole.MESTRE && currentTrip?.isActive) {
            const distanceMoved = lastRecordedPosRef.current ? calculateDistance(lastRecordedPosRef.current, newPoint) : Infinity;
            if (distanceMoved > 5) {
              const updated = storageService.updateTripPath(currentTrip.code, newPoint);
              if (updated) {
                setCurrentTrip({...updated});
                lastRecordedPosRef.current = newPoint;
              }
            }
          }
        },
        () => setError("GPS inacessível."),
        { enableHighAccuracy: true, timeout: 5000, maximumAge: 0 }
      );
      watchIdRef.current = id;
    }
    return () => { if (watchIdRef.current !== null) navigator.geolocation.clearWatch(watchIdRef.current); };
  }, [role, currentTrip]);

  useEffect(() => {
    if (role === UserRole.SEGUIDOR && currentTrip) {
      simulationIntervalRef.current = setInterval(() => {
        const trip = storageService.getTripByCode(currentTrip.code);
        if (trip) {
          setCurrentTrip({...trip});
          if (trip.path.length > 0) setMasterPos(trip.path[trip.path.length - 1]);
        }
      }, 3000);
    }
    return () => { if (simulationIntervalRef.current) clearInterval(simulationIntervalRef.current); };
  }, [role, currentTrip]);

  useEffect(() => {
    if (selectedDest && userPos) {
      fetchRoadRoute(userPos, selectedDest).then(route => setPlannedRoute(route));
    }
  }, [selectedDest, userPos]);

  const handleSearchDestination = async () => {
    if (!searchQuery.trim()) return;
    setIsSearching(true);
    setError(null);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Localize coordenadas exatas para: "${searchQuery}".`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              lat: { type: Type.NUMBER },
              lng: { type: Type.NUMBER },
              name: { type: Type.STRING }
            },
            required: ["lat", "lng", "name"]
          }
        }
      });
      const result = JSON.parse(response.text);
      setSelectedDest(result);
    } catch (err) {
      setError("Local não encontrado.");
    } finally {
      setIsSearching(false);
    }
  };

  const handleStartTrip = () => {
    const code = Math.random().toString(36).substring(2, 8).toUpperCase();
    const newTrip: Trip = {
      id: Date.now().toString(),
      code,
      name: "Viagem em Grupo",
      masterId: "me",
      destination: selectedDest || undefined,
      plannedRoute: plannedRoute.length > 0 ? plannedRoute : undefined,
      path: userPos ? [userPos] : [],
      isActive: true,
      createdAt: Date.now()
    };
    storageService.saveTrip(newTrip);
    setCurrentTrip(newTrip);
    lastRecordedPosRef.current = userPos;
    setRole(UserRole.MESTRE);
    setIsConfiguringTrip(false);
    setIsBottomSheetOpen(true);
  };

  if (role === UserRole.NONE && !isConfiguringTrip) {
    return (
      <div className="h-full w-full bg-slate-900 flex flex-col items-center justify-center p-6 text-white overflow-hidden">
        <div className="mb-12 text-center">
          <div className="bg-blue-600 w-20 h-20 rounded-3xl flex items-center justify-center mx-auto mb-6 shadow-2xl">
            <Navigation size={40} className="text-white" />
          </div>
          <h1 className="text-4xl font-extrabold mb-3 tracking-tight">Siga o Mestre</h1>
          <p className="text-slate-400">Comboio inteligente para viagens em grupo.</p>
        </div>
        <div className="w-full max-w-sm space-y-4">
          <button onClick={() => setIsConfiguringTrip(true)} className="w-full bg-blue-600 text-white font-bold py-5 px-6 rounded-2xl flex items-center justify-between shadow-xl">
            <div className="flex items-center"><Play size={24} className="mr-4 fill-white"/> Ser o Mestre</div>
            <ChevronUp className="rotate-90 opacity-40" />
          </button>
          <div className="relative py-6">
            <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-slate-800"></div></div>
            <div className="relative flex justify-center text-xs"><span className="bg-slate-900 px-4 text-slate-500 font-bold tracking-widest uppercase">Ou</span></div>
          </div>
          <input type="text" placeholder="Código de 6 dígitos" className="w-full bg-slate-800 border border-slate-700 rounded-2xl px-5 py-5 text-white uppercase text-center text-xl font-mono tracking-widest focus:ring-2 focus:ring-blue-500 transition-all" value={inputCode} onChange={(e) => setInputCode(e.target.value)} />
          <button onClick={() => { const trip = storageService.getTripByCode(inputCode); if(trip){ setCurrentTrip(trip); setRole(UserRole.SEGUIDOR); }else{ setError("Código inválido."); } }} disabled={!inputCode} className="w-full bg-white text-slate-900 font-bold py-5 px-6 rounded-2xl flex items-center justify-center active:scale-95 transition-all disabled:opacity-50">
            <Users size={24} className="mr-3" /> Seguir um Mestre
          </button>
          {error && <p className="text-red-400 text-sm text-center mt-2">{error}</p>}
        </div>
      </div>
    );
  }

  if (isConfiguringTrip) {
    return (
      <div className="fixed inset-0 flex flex-col bg-white overflow-hidden">
        {/* Header Fixo */}
        <div className="relative h-16 bg-slate-900 text-white flex items-center px-4 shrink-0 z-50 shadow-md">
          <button onClick={() => setIsConfiguringTrip(false)} className="flex items-center text-slate-400">
            <ArrowLeft className="mr-2" size={20} /> Voltar
          </button>
          <div className="flex-1 text-center font-bold text-lg">Definir Destino</div>
          <div className="w-10"></div>
        </div>

        {/* Área do Mapa */}
        <div className="flex-grow relative w-full overflow-hidden">
          <MapComponent 
            userPos={userPos} 
            masterPos={null} 
            trip={selectedDest ? { destination: selectedDest, plannedRoute: plannedRoute, path: [] } as any : null} 
            role={UserRole.MESTRE}
            onMapClick={(lat, lng) => setSelectedDest({ lat, lng, name: "Local marcado no mapa" })}
            isSelectingDestination={true}
          />

          {/* Overlay da Barra de Pesquisa */}
          <div className="absolute top-4 left-4 right-4 z-[1000] flex space-x-2">
            <div className="relative flex-1 shadow-2xl">
              <input 
                type="text" 
                placeholder="Para onde vamos?" 
                className="w-full pl-11 pr-4 py-4 rounded-2xl border-none focus:ring-2 focus:ring-blue-500 text-slate-900 shadow-xl"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSearchDestination()}
              />
              <Search className="absolute left-4 top-4.5 text-slate-400" size={20} />
            </div>
            <button onClick={handleSearchDestination} className="bg-blue-600 text-white px-5 rounded-2xl shadow-xl active:scale-95 transition-all">
              {isSearching ? <Loader2 className="animate-spin" size={24} /> : <Search size={24} />}
            </button>
          </div>

          {/* Card de Confirmação (Inferior) */}
          {selectedDest && (
            <div className="absolute bottom-6 left-4 right-4 z-[1000] bg-white p-6 rounded-3xl shadow-[0_20px_60px_rgba(0,0,0,0.3)] animate-in slide-in-from-bottom duration-300">
              <div className="flex items-start space-x-4 mb-6">
                <div className="bg-blue-100 p-3 rounded-2xl"><MapPin className="text-blue-600" size={28} /></div>
                <div className="flex-1 min-w-0">
                  <div className="text-[10px] font-black text-blue-600 uppercase tracking-widest mb-1">Confirmar Destino</div>
                  <div className="text-slate-900 font-extrabold text-xl leading-tight line-clamp-2">{selectedDest.name}</div>
                </div>
              </div>
              <button onClick={handleStartTrip} className="w-full bg-slate-900 text-white font-black py-5 rounded-2xl shadow-xl active:scale-95 transition-all flex items-center justify-center text-lg">
                <Navigation size={22} className="mr-3 text-blue-400" /> Iniciar Comboio
              </button>
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 w-full h-full overflow-hidden bg-slate-100">
      <div className="absolute inset-0">
        <MapComponent userPos={userPos} masterPos={masterPos} trip={currentTrip} role={role} />
      </div>

      {/* Header Overlay */}
      <div className="absolute top-4 left-4 right-4 z-[500]">
        <div className="bg-white/95 backdrop-blur-md rounded-2xl p-4 shadow-xl flex items-center justify-between border border-white/40">
          <div className="flex items-center space-x-3">
            <div className={`${role === UserRole.MESTRE ? 'bg-blue-600' : 'bg-red-500'} w-11 h-11 rounded-2xl flex items-center justify-center text-white shadow-lg`}>
              {role === UserRole.MESTRE ? '👑' : '🚗'}
            </div>
            <div>
              <h2 className="font-extrabold text-slate-900 leading-none">
                {role === UserRole.MESTRE ? 'Liderando' : 'Seguindo Mestre'}
              </h2>
              <div className="flex items-center text-[10px] text-green-600 font-black uppercase tracking-widest mt-1">
                <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse mr-2"></div> AO VIVO
              </div>
            </div>
          </div>
          <button onClick={() => { setRole(UserRole.NONE); setCurrentTrip(null); }} className="p-2 text-slate-400 hover:text-red-500 transition-colors bg-slate-50 rounded-xl">
            <LogOut size={20} />
          </button>
        </div>
      </div>

      {/* Bottom Sheet */}
      <div className={`absolute bottom-0 left-0 right-0 bg-white shadow-[0_-15px_40px_rgba(0,0,0,0.1)] rounded-t-[40px] z-[1000] transition-transform duration-500 ${isBottomSheetOpen ? 'translate-y-0' : 'translate-y-[calc(100%-70px)]'}`}>
        <div className="w-full flex flex-col items-center py-4 cursor-pointer" onClick={() => setIsBottomSheetOpen(!isBottomSheetOpen)}>
          <div className="w-14 h-1.5 bg-slate-200 rounded-full"></div>
        </div>

        <div className="px-6 pb-10 space-y-6">
          {currentTrip?.destination && (
            <div className="bg-slate-50 p-4 rounded-2xl flex items-center space-x-4 border border-slate-100">
              <div className="bg-green-100 p-2 rounded-xl text-green-600"><MapPin size={24} /></div>
              <div className="flex-1 min-w-0">
                <div className="text-[10px] text-slate-400 font-black uppercase tracking-widest mb-1">Destino Final</div>
                <div className="font-bold text-slate-900 truncate">{currentTrip.destination.name}</div>
              </div>
            </div>
          )}

          <div className="flex items-center justify-between bg-blue-50 p-5 rounded-3xl border border-blue-100">
            <div>
              <div className="text-[10px] text-blue-400 font-black uppercase tracking-widest mb-1">Código do Comboio</div>
              <div className="text-3xl font-mono font-black text-blue-600 tracking-tighter">{currentTrip?.code}</div>
            </div>
            <button onClick={() => { navigator.clipboard.writeText(currentTrip?.code || ''); setCopied(true); setTimeout(() => setCopied(false), 2000); }} className="bg-white p-4 rounded-2xl shadow-sm text-blue-600 active:scale-90 transition-all">
              {copied ? <Check size={24} className="text-green-500" /> : <Copy size={24} />}
            </button>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100 text-center">
              <div className="text-[10px] text-slate-400 uppercase font-black tracking-widest mb-1">Pontos GPS</div>
              <div className="font-black text-xl text-slate-800">{currentTrip?.path.length}</div>
            </div>
            <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100 text-center">
              <div className="text-[10px] text-slate-400 uppercase font-black tracking-widest mb-1">Início</div>
              <div className="font-black text-xl text-slate-800">{new Date(currentTrip?.createdAt || 0).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</div>
            </div>
          </div>

          {role === UserRole.MESTRE && currentTrip?.isActive && (
            <button onClick={() => { if(currentTrip) storageService.saveTrip({...currentTrip, isActive: false}); setCurrentTrip(prev => prev ? {...prev, isActive: false} : null); }} className="w-full bg-red-500 text-white font-black py-5 rounded-2xl shadow-lg active:scale-95 transition-all text-lg">
              Encerrar Viagem
            </button>
          )}

          <button className="w-full border-2 border-slate-100 py-4 rounded-2xl font-bold text-slate-500 flex items-center justify-center hover:bg-slate-50">
            <Share2 className="mr-3" size={20} /> Convidar via WhatsApp
          </button>
        </div>
      </div>
    </div>
  );
};

export default App;

