          <div className="flex items-center justify-between bg-blue-50 p-5 rounded-3xl border border-blue-100">
            <div>
              <div className="text-[10px] text-blue-400 font-black uppercase tracking-widest mb-1">Código do Comboio</div>
              <div className="text-3xl font-mono font-black text-blue-600 tracking-tighter">{currentTrip?.code}</div>
            </div>
            <button onClick={() => { navigator.clipboard.writeText(currentTrip?.code || ''); setCopied(true); setTimeout(() => setCopied(false), 2000); }} className="bg-white p-4 rounded-2xl shadow-sm text-blue-600 active:scale-90 transition-all">
              {copied ? <Check size={24} className="text-green-500" /> : <Copy size={24} />}
