  MESTRE = 'MESTRE',
  SEGUIDOR = 'SEGUIDOR',
  NONE = 'NONE'
}

export interface Trip {
  id: string;
  code: string;
  name: string;
  masterId: string;
  destination?: Destination;
  plannedRoute?: [number, number][]; // Polilinha do caminho real pelas ruas
  path: GeoPoint[];
  isActive: boolean;
  createdAt: number;
}

